$encoding=New-Object Text.UTF8Encoding($false)
function Read-Local([string]$Path){[IO.File]::ReadAllText((Join-Path $root $Path))}
function Body([string]$Text){[regex]::Replace($Text,'(?s)\A---\r?\n.*?\r?\n---\r?\n\r?\n','')}
function Git-Read([string[]]$Arguments){
 $p=New-Object Diagnostics.ProcessStartInfo;$p.FileName='git';$p.WorkingDirectory=$root;$p.Arguments=(@($Arguments|ForEach-Object{'"'+$_.Replace('"','\"')+'"'}) -join ' ');$p.UseShellExecute=$false;$p.RedirectStandardOutput=$true;$p.RedirectStandardError=$true;$p.StandardOutputEncoding=$encoding;$p.StandardErrorEncoding=$encoding
 $proc=[Diagnostics.Process]::Start($p);$stdout=$proc.StandardOutput.ReadToEnd();$stderr=$proc.StandardError.ReadToEnd();$proc.WaitForExit();[pscustomobject]@{exit_code=$proc.ExitCode;stdout=$stdout;stderr=$stderr}
}
function Git-Value([string[]]$Arguments){$v=Git-Read $Arguments;if($v.exit_code){throw ('Falha na leitura Git: '+$v.stderr)};$v.stdout.TrimEnd("`r","`n")}
