$newAllowed=@('governance/sources/knowledge-foundation-finalization-mandate-01.md','governance/decisions/m01-presidential-ratification-01.md','governance/reviews/cto-ni-final-review-01.md','governance/mandates/m01-normative-effectiveness-01.md','validation/AC-KF-FINAL-PROPOSED.md','validation/VAL-KF-FINALIZATION-01.md','validation/validate-kf-finalization.ps1','validation/evidence/kf-finalization-baseline.json','validation/evidence/kf-finalization-validation.json','validation/evidence/kf-finalization.diff','status/KF-FINALIZATION-HANDOFF.md')
$head=Git-Value @('rev-parse','HEAD');$branch=Git-Value @('branch','--show-current');$blob=Git-Value @('rev-parse',($checkpoint+':'+$approvedPath));$workingBlob=Git-Value @('hash-object',('--path='+$approvedPath),$approvedPath)
if($head -ne $checkpoint -or $branch -ne 'dev' -or $blob -ne $expectedBlob -or $workingBlob -ne $expectedBlob){$issues.Add('Checkpoint, branch ou instrumento ratificado divergem')}
if($baseline.head -ne $checkpoint -or $baseline.initial_working_tree.Count -ne 0 -or $baseline.files.Count -ne 94){$issues.Add('Baseline inicial divergente')}
if((Git-Value @('diff','--cached','--name-only'))){$issues.Add('Index contém alterações staged não autorizadas')}
$preservation=@();foreach($f in $baseline.files){$p=Join-Path $root $f.path;if(-not (Test-Path -LiteralPath $p)){$issues.Add('Arquivo inicial excluído: '+$f.path);continue};if($f.path -notin $modifiedAllowed){$sha=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLower();$same=$sha -eq $f.sha256;$preservation+=[ordered]@{path=$f.path;before_sha256=$f.sha256;after_sha256=$sha;unchanged=$same};if(-not $same){$issues.Add('Fonte/evidência/instrumento preservado foi alterado: '+$f.path)}}}
$sourceText=[IO.File]::ReadAllText($SourceAttachment);$sourceSha=(Get-FileHash -Algorithm SHA256 -LiteralPath $SourceAttachment).Hash.ToLower();$sourceCopy=Read-Local 'governance/sources/knowledge-foundation-finalization-mandate-01.md'
if($sourceSha -ne $baseline.source_attachment_sha256 -or -not $sourceCopy.EndsWith($sourceText) -or -not $sourceCopy.Contains($sourceSha)){$issues.Add('Mandato recebido/cópia canônica divergem')}
$decision=Read-Local 'governance/decisions/m01-presidential-ratification-01.md';$review=Read-Local 'governance/reviews/cto-ni-final-review-01.md';$effective=Read-Local 'governance/mandates/m01-normative-effectiveness-01.md'
$quote=[regex]::Match($sourceText,'(?m)^> (Deliberação expressa da Presidência:[^\r\n]+)').Groups[1].Value
if(-not $quote -or -not $decision.Contains('> '+$quote)){$issues.Add('Deliberação não foi registrada integralmente')}
foreach($v in @('ANCESTRALIDADE-PRESIDENCY-DEC-M01-RATIFICATION-01','2026-11-27',$checkpoint,$expectedBlob,'APPROVED','NONE','sessão CTO')){if(-not $decision.Contains($v)){$issues.Add('Ratificação sem campo requerido: '+$v)}}
foreach($v in @('CTO-ANCESTRALIDADE-NI-FINAL-REVIEW-01','NORMATIVE_INTEGRATION_ACCEPTED — READY_FOR_PRESIDENTIAL_RATIFICATION','16 PASS')){if(-not $review.Contains($v)){$issues.Add('Registro da revisão CTO incompleto: '+$v)}}
foreach($v in @('presidential_ratification: APPROVED','normative_baseline: RATIFIED','effective_date: "2026-11-27"','effective: true',$checkpoint,$expectedBlob)){if(-not $effective.Contains($v)){$issues.Add('Vigência sem estado requerido: '+$v)}}
$approved=Read-Local $approvedPath;$immutable=Git-Value @('show',($checkpoint+':'+$approvedPath));if($approved.Replace("`r`n","`n").TrimEnd() -cne $immutable.Replace("`r`n","`n").TrimEnd()){$issues.Add('Texto ratificado foi alterado')}
$sections=[regex]::Matches($approved,'(?m)^## \d{1,2}\.').Count;$acs=[regex]::Matches($approved,'(?m)^### AC-\d{2} —').Count
if($sections -ne 36 -or $acs -ne 18){$issues.Add('Estrutura do mandato ratificado mudou')}
$decisions=Read-Local 'decisions/DECISION-REGISTER.md';$oldDecisions=Git-Value @('show',($checkpoint+':decisions/DECISION-REGISTER.md'))
$decRows=@([regex]::Matches($decisions,'(?m)^\| DEC-\d{2} \|[^\r\n]+')|ForEach-Object{$_.Value});$oldDecRows=@([regex]::Matches($oldDecisions,'(?m)^\| DEC-\d{2} \|[^\r\n]+')|ForEach-Object{$_.Value});if($decRows.Count -ne 16 -or ($decRows -join "`n") -cne ($oldDecRows -join "`n")){$issues.Add('DEC-01–16 substantivas não preservadas')}
$trace=Read-Local 'validation/M01-NORMATIVE-TRACEABILITY.md';$oldTrace=Body (Git-Value @('show',($checkpoint+':validation/M01-NORMATIVE-TRACEABILITY.md')));$traceTail=$oldTrace.Substring($oldTrace.IndexOf("`n")).Trim()
if(-not $trace.Replace("`r`n","`n").TrimEnd().EndsWith($traceTail.Replace("`r`n","`n"))){$issues.Add('Matriz NI aceita foi modificada substantivamente')}
$mapping=(Read-Local 'validation/evidence/ni-reconciliation.json')|ConvertFrom-Json;if($mapping.forward_ac.Count -ne 18 -or $mapping.reverse_ac.Count -ne 18 -or $mapping.construction_ac.Count -ne 26){$issues.Add('Rastreabilidade histórica alterada')}
$matrix=Read-Local 'validation/AC-KF-FINAL-PROPOSED.md';$definition='AC-KF-03-R1: mandato normativo vigente do M01 disponível, integral, formalmente aprovado pela Presidência, versionado, rastreável e reconciliado com as decisões e requisitos aplicáveis.'
if(-not $matrix.Contains($definition) -or -not $approved.Contains($definition)){$issues.Add('Definição aprovada R1 alterada')}
$kfRows=@([regex]::Matches($matrix,'(?m)^\| (AC-KF-\d{2}(?:-R1)?) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object{[ordered]@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}});$kfCounts=@{};foreach($s in @('PASS','FAIL','BLOCKED','NOT_EXECUTED')){$kfCounts[$s]=@($kfRows|Where-Object result -eq $s).Count}
if($kfRows.Count -ne 15 -or $kfCounts.PASS -ne 12 -or $kfCounts.BLOCKED -ne 1 -or $kfCounts.NOT_EXECUTED -ne 2 -or @($kfRows|Where-Object{$_.id -eq 'AC-KF-03-R1' -and $_.result -eq 'BLOCKED'}).Count -ne 1){$issues.Add('Matriz KF proposta inconsistente ou R1 promovido prematuramente')}
$state=Read-Local 'status/CURRENT-STATUS.md';foreach($v in @('READY_FOR_KNOWLEDGE_FOUNDATION_FINAL_ACCEPTANCE','PRESIDENTIAL_RATIFICATION APPROVED','NORMATIVE_BASELINE RATIFIED','EFFECTIVE_DATE 2026-11-27','EFFECTIVE TRUE','SUBSTANTIVE_NORMATIVE_DEPENDENCY_RESOLVED','FINAL_CLASSIFICATION_PENDING_CTO','AC-KF-03-R1 BLOCKED','NOT_ESTABLISHED','NOT_FROZEN','T02–T04 OPEN','CTO_KNOWLEDGE_FOUNDATION_FINAL_ACCEPTANCE_REVIEW')){if(-not $state.Replace('**','').Contains($v)){$issues.Add('Estado corrente incompleto: '+$v)}}
foreach($p in $modifiedAllowed){$t=Read-Local $p;if(-not $t.Contains('m01-normative-effectiveness-01.md') -or -not $t.Contains('CTO_KNOWLEDGE_FOUNDATION_FINAL_ACCEPTANCE_REVIEW')){$issues.Add('Dependente sem vigência ou gate corrente: '+$p)}}
$docs=@(Get-ChildItem -Recurse -File -LiteralPath $root -Filter '*.md'|Where-Object{$_.FullName -notmatch '[\\/]\.git[\\/]'});$ids=@{};$references=0;$metadata=@()
foreach($f in $docs){$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');$t=[IO.File]::ReadAllText($f.FullName);$m=[regex]::Match($t,'(?s)\A---\r?\n(.*?)\r?\n---\r?\n');if(-not $m.Success){$issues.Add('Metadados ausentes: '+$rel);continue};$h=$m.Groups[1].Value;foreach($key in @('id','title','version','status','authority','maintainer','module','classification','references','supersedes','last_updated')){if($h -notmatch ('(?m)^'+$key+':')){$issues.Add('Metadado ausente: '+$rel+'/'+$key)}};$id=[regex]::Match($h,'(?m)^id:\s*(\S+)').Groups[1].Value;if($ids.ContainsKey($id)){$issues.Add('ID duplicado: '+$id)}else{$ids[$id]=$rel}
 if($h -notmatch '(?m)^classification: PUBLIC\s*$'){$issues.Add('Classificação a tratar: '+$rel)};if($h -match '"[ \t]+- "'){$issues.Add('Lista de referências malformada: '+$rel)};if($t.Contains([char]0xFFFD) -or ([regex]::Matches($t,'(?m)^```').Count % 2)){$issues.Add('Codificação/fence inválido: '+$rel)}
 $targets=@([regex]::Matches($t.Substring($m.Length),'\]\(([^)]+)\)')|ForEach-Object{$_.Groups[1].Value});$targets+=@([regex]::Matches($h,'(?m)^  - "([^"\r\n]+)"\s*$')|ForEach-Object{$_.Groups[1].Value});foreach($target in $targets){if($target -match '^(https?:|mailto:|#)'){continue};$references++;$resolved=[IO.Path]::GetFullPath((Join-Path $f.DirectoryName (($target.Trim('<','>') -split '#',2)[0])));if($resolved -in @((Join-Path $root $outputPath),(Join-Path $root $diffPath))){continue};if(-not (Test-Path -LiteralPath $resolved)){$issues.Add('Referência inexistente: '+$rel+' -> '+$target)}}
 foreach($pattern in @('gh[pousr]_[A-Za-z0-9]{30,}','github_pat_[A-Za-z0-9_]{40,}','AKIA[0-9A-Z]{16}','-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----','\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b','\b\d{3}\.\d{3}\.\d{3}-\d{2}\b','C:[\\/]Users[\\/]')){if([regex]::IsMatch($t,$pattern,[Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível, conteúdo omitido: '+$rel)}}
 if($rel -in $modifiedAllowed){$prior=Git-Value @('show',($checkpoint+':'+$rel));$v=[regex]::Match($prior,'(?m)^version: "([^"]+)"').Groups[1].Value;$parts=$v.Split('.');$next=$parts[0]+'.'+([int]$parts[1]+1);if($h -notmatch ('(?m)^version: "'+[regex]::Escape($next)+'"') -or -not $h.Contains($checkpoint+':'+$rel+'@'+$v)){$issues.Add('Versão/referência anterior inválida: '+$rel)}}
 if($rel -in $modifiedAllowed -or $rel -in $newAllowed){$metadata+=[ordered]@{path=$rel;id=$id;version=[regex]::Match($h,'(?m)^version: "([^"]+)"').Groups[1].Value;status=[regex]::Match($h,'(?m)^status:\s*(\S+)').Groups[1].Value}}
}
$val=Read-Local 'validation/VAL-KF-FINALIZATION-01.md';$finalRows=@([regex]::Matches($val,'(?m)^\| (AC-FINAL-\d{2}) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object{[ordered]@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}});$finalCounts=@{};foreach($s in @('PASS','FAIL','BLOCKED','NOT_EXECUTED')){$finalCounts[$s]=@($finalRows|Where-Object result -eq $s).Count};if($finalRows.Count -ne 10 -or $finalCounts.PASS -ne 10){$issues.Add('Matriz AC-FINAL-01–10 inconsistente')}
$modified=@(Lines (Git-Value @('diff','--name-only')));$new=@(Lines (Git-Value @('ls-files','--others','--exclude-standard')));foreach($p in @($outputPath,$diffPath)){if($new -notcontains $p){$new+=$p}};foreach($p in @($modified)+@($new)){if($p -notin $modifiedAllowed -and $p -notin $newAllowed){$issues.Add('Arquivo fora da intervenção restrita: '+$p)}}
$diffCheck=Git-Read @('-c','core.safecrlf=false','diff','--check');if($diffCheck.exit_code){$issues.Add('git diff --check falhou: '+$diffCheck.stdout)}
$result=[ordered]@{id='ANCESTRALIDADE-VAL-KF-FINALIZATION-01-LOCAL-RESULT';date='2026-11-27';executor='AGENT_CODER';branch=$branch;initial_head=$baseline.head;head=$head;initial_working_tree='CLEAN';checkpoint=$checkpoint;ratified_blob=$blob;working_blob=$workingBlob;approved_file_unchanged=($blob -eq $workingBlob);substantive_changes=0;approved_sections=$sections;approved_acceptance_criteria=$acs;source_attachment_sha256=$sourceSha;source_copy_sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $root 'governance/sources/knowledge-foundation-finalization-mandate-01.md')).Hash.ToLower();ratification='APPROVED';normative_baseline='RATIFIED';effective_date='2026-11-27';effective=$true;historical_files_preserved=$preservation.Count;preservation=$preservation;modified=$modified;new=$new;metadata=$metadata;markdown_files=$docs.Count;unique_ids=$ids.Count;references_checked=$references;DEC_rows_preserved=$decRows.Count;COR_T01_preserved_by_immutable_mandate=$true;traceability_text_preserved=$true;namespaces=@{MVP=18;CONSOLIDATED=18;CONSTRUCTION_proposed=26};ac_final=$finalRows;ac_final_counts=$finalCounts;ac_kf_proposed=$kfRows;ac_kf_counts=$kfCounts;C10_substantive_dependency='RESOLVED';C10_final_classification='PENDING_FINAL_CTO_ACCEPTANCE';AC_KF_03_R1='BLOCKED';engineering_readiness='NOT_ESTABLISHED';domain_contracts='NOT_FROZEN';application_tests='NOT_EXECUTED';remote_independent_recovery_definitive_checkpoint='NOT_EXECUTED';historical_evidence_overwritten=$false;historical_validators_reexecuted=$false;git_write_operations=$false;diff_check=$(if($diffCheck.exit_code){'FAIL'}else{'PASS'});diff_path=$diffPath;diff_scope='All modified and new files including this JSON; diff itself excluded to avoid self-reference';errors=@($issues);result=$(if($issues.Count){'FAIL'}else{'PASS'});delivery='READY_FOR_KNOWLEDGE_FOUNDATION_FINAL_ACCEPTANCE';next_gate='CTO_KNOWLEDGE_FOUNDATION_FINAL_ACCEPTANCE_REVIEW';limitations=@('Decision provenance is the user-supplied CTO mandate; no additional signature/session authentication claimed','No independent remote recovery of the definitive finalization checkpoint','Metadata/links/pattern checks are not a complete YAML parser, renderer, legal review or exhaustive sensitive-data audit','Received-byte hashes and working-tree hashes may differ in other checkouts due to line endings')}
[IO.File]::WriteAllText((Join-Path $root $outputPath),($result|ConvertTo-Json -Depth 14),$encoding)
# Diff completo: inclui novos arquivos e JSON desta execução; não se inclui a si próprio.
$fullDiff=Git-Value @('-c','core.safecrlf=false','diff','--no-ext-diff','--no-color');$fullDiff+="`n"
foreach($p in $new|Where-Object{$_ -ne $diffPath}|Sort-Object){$patch=Git-Read @('-c','core.safecrlf=false','diff','--no-index','--no-ext-diff','--no-color','--','/dev/null',$p);if($patch.exit_code -notin @(0,1)){throw ('Falha ao preparar diff de novo arquivo: '+$p)};$fullDiff+=$patch.stdout+"`n"}
[IO.File]::WriteAllText((Join-Path $root $diffPath),$fullDiff,$encoding)
foreach($p in @($modified)+@($new|Where-Object{$_ -ne $diffPath})){if(-not $fullDiff.Contains('+++ b/'+$p)){throw ('Diff incompleto: '+$p)}}
[pscustomobject]@{result=$result.result;markdown_files=$docs.Count;references_checked=$references;preserved_files=$preservation.Count;modified=$modified.Count;created=$new.Count;ac_final=$finalCounts;ac_kf_proposed=$kfCounts;errors=@($issues)}|ConvertTo-Json -Depth 6
if($issues.Count){throw 'Validação da finalização falhou; consultar evidência própria'}
